// Score System 1 (ollaya decision model) against ground truth, per row.
// Routing rule mirrored from the demo workflows' Route Decision node:
//   confidence < 0.6 -> human_review; urgent >= 0.7 -> page_oncall:<team>; else queue:<team>
// Everything is written as TEXT so a CSV-imported Data Table (all string columns) accepts it.
// Only s1_* columns are written - the expected_* label columns are never touched.
// s1_status makes freshness fail-closed in the table itself: at run start every row is marked
// STALE; as a row completes, its status becomes 'current as of <s1_run_at>'. A row still showing
// STALE means its s1_* values are from a previous run and must not be read as current.
const row = $('When fetching a dataset row').first().json;
const s1raw = $('Laya Decide (S1)').first().json;

const CONF_MIN = 0.6, URGENT_MIN = 0.7;
const routeOf = (team, conf, urgentProb) => {
  if (team === null || team === undefined || team === '' || conf === null || conf === undefined) return 'no_answer';
  if (conf < CONF_MIN) return 'human_review';
  if (urgentProb >= URGENT_MIN) return 'page_oncall:' + team;
  return 'queue:' + team;
};

const s1_team = s1raw.answers?.team?.choice ?? '';
const s1_confidence = s1raw.answers?.team?.confidence ?? null;
const s1_urgent = s1raw.answers?.urgent?.noul ?? null;
// Two same-boundary latencies (the S2 workflow measures its call the same two ways):
//   s1_wall_ms   = client-side wall time around the HTTP call (identical measurer both systems)
//   s1_server_ms = ollaya's own server-reported total_duration, ns -> ms (load + eval)
const s1_server_ms = Math.round((s1raw.total_duration || 0) / 1e6);
const s1_run_at = new Date().toISOString();
const s1_wall_ms = Date.now() - Number($('Mark Call Start').first().json.call_start_ms || 0);
const s1_route = routeOf(s1_team, s1_confidence, s1_urgent);
// Backend-reported token usage - never invented: a number is reported verbatim
// (0 is a real measurement - this classifier generates no text), anything else is blank.
const tok = (v) => (typeof v === 'number' ? String(v) : '');
const s1_input_tokens = tok(s1raw.usage?.input_tokens);
const s1_output_tokens = tok(s1raw.usage?.output_tokens);

const expected_team = String(row.expected_team ?? '').trim();
const expected_urgent = String(row.expected_urgent ?? '').trim() === '1';
const expected_route = String(row.expected_route ?? '').trim();

const flag = (ok) => (ok ? 'correct' : 'WRONG');
const s1_team_correct = expected_team ? flag(s1_team === expected_team) : '';
const s1_urgent_correct = flag((s1_urgent !== null && s1_urgent >= URGENT_MIN) === expected_urgent);
const s1_route_correct = flag(s1_route === expected_route);

const fmt = (v) => (typeof v === 'number' ? String(Math.round(v * 1000) / 1000) : String(v ?? ''));

return [{ json: {
  s1_team,
  s1_confidence: fmt(s1_confidence),
  s1_urgent: fmt(s1_urgent),
  s1_server_ms: String(s1_server_ms),
  s1_wall_ms: String(s1_wall_ms),
  s1_input_tokens,
  s1_output_tokens,
  s1_run_at,
  s1_status: 'current as of ' + s1_run_at,
  s1_route,
  s1_team_correct,
  s1_urgent_correct,
  s1_route_correct
} }];
